  const { authkitMiddleware } = await import("@workos-inc/authkit-nextjs");
  return authkitMiddleware({
    middlewareAuth: {
      enabled: true,
      unauthenticatedPaths: ["/auth/callback"],
    },
  })(request);
}

export const config = {
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
  ],
};

