1	use anyhow::Result;
2	use regex::Regex;
3	use serde::Deserialize;
4	use std::path::Path;
5	
6	#[derive(Debug, Clone, Deserialize)]
7	pub struct FilterConfig {
8	    pub command: CommandMatch,
9	    #[serde(default)]
10	    pub strip_ansi: Option<bool>,
11	    #[serde(default)]
12	    pub replace: Vec<ReplaceRule>,
13	    #[serde(default)]
14	    pub match_output: Option<MatchOutputRule>,
15	    #[serde(default)]
16	    pub strip_lines: Vec<StripLinesRule>,
17	    #[serde(default)]
18	    pub truncate_lines: Option<TruncateLinesRule>,
19	    #[serde(default)]
20	    pub head_tail: Option<HeadTailRule>,
21	    #[serde(default)]
22	    pub max_lines: Option<usize>,
23	    #[serde(default)]
24	    pub on_empty: Option<String>,
25	}
26	
27	#[derive(Debug, Clone, Deserialize)]
28	pub struct CommandMatch {
29	    pub name: String,
30	    #[serde(default)]
31	    pub args_contain: Vec<String>,
32	}
33	
34	#[derive(Debug, Clone, Deserialize)]
35	pub struct ReplaceRule {
36	    pub pattern: String,
37	    pub replacement: String,
38	}
39	
40	#[derive(Debug, Clone, Deserialize)]
41	pub struct MatchOutputRule {
42	    pub pattern: String,
43	    #[serde(default)]
44	    pub invert: bool,
45	}
46	
47	#[derive(Debug, Clone, Deserialize)]
48	pub struct StripLinesRule {
49	    pub pattern: String,
50	}
51	
52	#[derive(Debug, Clone, Deserialize)]
53	pub struct TruncateLinesRule {
54	    pub max_length: usize,
55	    #[serde(default = "default_suffix")]
56	    pub suffix: String,
57	}
58	
59	fn default_suffix() -> String {
60	    "…".to_string()
61	}
62	
63	#[derive(Debug, Clone, Deserialize)]
64	pub struct HeadTailRule {
65	    pub head: usize,
66	    pub tail: usize,
67	    #[serde(default = "default_separator")]
68	    pub separator: String,
69	}
70	
71	fn default_separator() -> String {
72	    "\n... ({omitted} lines omitted) ...\n".to_string()
73	}
74	
75	#[derive(Default)]
76	pub struct FilterPipeline {
77	    configs: Vec<FilterConfig>,
78	}
79	
80	impl FilterPipeline {
81	    pub fn new() -> Self {
82	        Self::default()
83	    }
84	
85	    pub fn load_from_dir(dir: &Path) -> Result<Self> {
86	        let mut configs = Vec::new();
87	        if dir.exists() {
88	            for entry in std::fs::read_dir(dir)? {
89	                let entry = entry?;
90	                let path = entry.path();
91	                if path.extension().is_some_and(|e| e == "toml") {
92	                    let content = std::fs::read_to_string(&path)?;
93	                    let config: FilterConfig = toml::from_str(&content)?;
94	                    configs.push(config);
95	                }
96	            }
97	        }
98	        Ok(Self { configs })
99	    }
100	
101	    pub fn add_config(&mut self, config: FilterConfig) {
102	        self.configs.push(config);
103	    }
104	
105	    pub fn find_filter(&self, command: &str, args: &[String]) -> Option<&FilterConfig> {
106	        self.configs.iter().find(|c| {
107	            if c.command.name != command {
108	                return false;
109	            }
110	            c.command.args_contain.iter().all(|required| {
111	                args.iter().any(|a| a.contains(required.as_str()))
112	            })
113	        })
114	    }
115	
116	    pub fn apply(&self, command: &str, args: &[String], output: &str) -> FilterResult {
117	        let config = match self.find_filter(command, args) {
118	            Some(c) => c,
119	            None => return FilterResult::passthrough(output),
120	        };
121	        apply_filter(config, output)
122	    }
123	}
124	
125	#[derive(Debug)]
126	pub struct FilterResult {
127	    pub output: String,
128	    pub input_len: usize,
129	    pub output_len: usize,
130	    pub filter_applied: bool,
131	}
132	
133	impl FilterResult {
134	    fn passthrough(output: &str) -> Self {
135	        let len = output.len();
136	        Self {
137	            output: output.to_string(),
138	            input_len: len,
139	            output_len: len,
140	            filter_applied: false,
141	        }
142	    }
143	}
144	
145	pub fn apply_filter(config: &FilterConfig, output: &str) -> FilterResult {
146	    let input_len = output.len();
147	    let mut text = output.to_string();
148	
149	    // Stage 1: strip_ansi
150	    if config.strip_ansi.unwrap_or(true) {
151	        text = stage_strip_ansi(&text);
152	    }
153	
154	    // Stage 2: replace
155	    for rule in &config.replace {
156	        text = stage_replace(&text, rule);
157	    }
158	
159	    // Stage 3: match_output
160	    if let Some(rule) = &config.match_output {
161	        text = stage_match_output(&text, rule);
162	    }
163	
164	    // Stage 4: strip_lines
165	    for rule in &config.strip_lines {
166	        text = stage_strip_lines(&text, rule);
167	    }
168	
169	    // Stage 5: truncate_lines
170	    if let Some(rule) = &config.truncate_lines {
171	        text = stage_truncate_lines(&text, rule);
172	    }
173	
174	    // Stage 6: head_tail
175	    if let Some(rule) = &config.head_tail {
176	        text = stage_head_tail(&text, rule);
177	    }
178	
179	    // Stage 7: max_lines
180	    if let Some(max) = config.max_lines {
181	        text = stage_max_lines(&text, max);
182	    }
183	
184	    // Stage 8: on_empty
185	    if let Some(fallback) = &config.on_empty {
186	        if text.trim().is_empty() {
187	            text = fallback.clone();
188	        }
189	    }
190	
191	    let output_len = text.len();
192	    FilterResult {
193	        output: text,
194	        input_len,
195	        output_len,
196	        filter_applied: true,
197	    }
198	}
199	
200	fn stage_strip_ansi(text: &str) -> String {
201	    match strip_ansi_escapes::strip_str(text) {
202	        s if s.is_empty() && !text.is_empty() => text.to_string(),
203	        s => s.to_string(),
204	    }
205	}
206	
207	fn stage_replace(text: &str, rule: &ReplaceRule) -> String {
208	    match Regex::new(&rule.pattern) {
209	        Ok(re) => re.replace_all(text, rule.replacement.as_str()).to_string(),
210	        Err(_) => text.to_string(),
211	    }
212	}
213	
214	fn stage_match_output(text: &str, rule: &MatchOutputRule) -> String {
215	    let re = match Regex::new(&rule.pattern) {
216	        Ok(r) => r,
217	        Err(_) => return text.to_string(),
218	    };
219	    let lines: Vec<&str> = text.lines().collect();
220	    let filtered: Vec<&str> = lines
221	        .into_iter()
222	        .filter(|line| {
223	            let matches = re.is_match(line);
224	            if rule.invert { !matches } else { matches }
225	        })
226	        .collect();
227	    filtered.join("\n")
228	}
229	
230	fn stage_strip_lines(text: &str, rule: &StripLinesRule) -> String {
231	    let re = match Regex::new(&rule.pattern) {
232	        Ok(r) => r,
233	        Err(_) => return text.to_string(),
234	    };
235	    text.lines()
236	        .filter(|line| !re.is_match(line))
237	        .collect::<Vec<_>>()
238	        .join("\n")
239	}
240	
241	fn stage_truncate_lines(text: &str, rule: &TruncateLinesRule) -> String {
242	    text.lines()
243	        .map(|line| {
244	            if line.len() > rule.max_length {
245	                let truncated: String = line.chars().take(rule.max_length).collect();
246	                format!("{}{}", truncated, rule.suffix)
247	            } else {
248	                line.to_string()
249	            }
250	        })
251	        .collect::<Vec<_>>()
252	        .join("\n")
253	}
254	
255	fn stage_head_tail(text: &str, rule: &HeadTailRule) -> String {
256	    let lines: Vec<&str> = text.lines().collect();
257	    let total = lines.len();
258	    if total <= rule.head + rule.tail {
259	        return text.to_string();
260	    }
261	    let head_part: Vec<&str> = lines[..rule.head].to_vec();
262	    let tail_part: Vec<&str> = lines[total - rule.tail..].to_vec();
263	    let omitted = total - rule.head - rule.tail;
264	    let sep = rule.separator.replace("{omitted}", &omitted.to_string());
265	    format!("{}{}{}", head_part.join("\n"), sep, tail_part.join("\n"))
266	}
267	
268	fn stage_max_lines(text: &str, max: usize) -> String {
269	    let lines: Vec<&str> = text.lines().collect();
270	    if lines.len() <= max {
271	        return text.to_string();
272	    }
273	    lines[..max].join("\n")
274	}
275	
276	#[cfg(test)]
277	mod tests {
278	    use super::*;
279	
280	    fn make_config(overrides: impl FnOnce(&mut FilterConfig)) -> FilterConfig {
281	        let mut c = FilterConfig {
282	            command: CommandMatch {
283	                name: "test".to_string(),
284	                args_contain: vec![],
285	            },
286	            strip_ansi: Some(false),
287	            replace: vec![],
288	            match_output: None,
289	            strip_lines: vec![],
290	            truncate_lines: None,
291	            head_tail: None,
292	            max_lines: None,
293	            on_empty: None,
294	        };
295	        overrides(&mut c);
296	        c
297	    }
298	
299	    #[test]
300	    fn test_strip_ansi() {
301	        let input = "\x1b[31mERROR\x1b[0m: something failed";
302	        let result = stage_strip_ansi(input);
303	        assert_eq!(result, "ERROR: something failed");
304	    }
305	
306	    #[test]
307	    fn test_replace() {
308	        let rule = ReplaceRule {
309	            pattern: r"\d+\.\d+s".to_string(),
310	            replacement: "X.Xs".to_string(),
311	        };
312	        let result = stage_replace("finished in 3.45s", &rule);
313	        assert_eq!(result, "finished in X.Xs");
314	    }
315	
316	    #[test]
317	    fn test_match_output_keep() {
318	        let rule = MatchOutputRule {
319	            pattern: r"^error".to_string(),
320	            invert: false,
321	        };
322	        let input = "info: ok\nerror: bad\nwarn: meh\nerror: worse";
