192	fn is_known_safe(token: &str) -> bool {
193	    // UUIDs
194	    if token.len() == 36 && token.chars().filter(|c| *c == '-').count() == 4 {
195	        return true;
196	    }
197	    // Git SHAs
198	    if token.len() == 40 && token.chars().all(|c| c.is_ascii_hexdigit()) {
199	        return true;
200	    }
201	    // Common hash prefixes
202	    if token.starts_with("sha256:") || token.starts_with("sha1:") {
203	        return true;
204	    }
