208	pub fn shannon_entropy(s: &str) -> f64 {
209	    if s.is_empty() {
210	        return 0.0;
211	    }
212	    let mut freq = [0u32; 256];
213	    for b in s.bytes() {
214	        freq[b as usize] += 1;
215	    }
216	    let len = s.len() as f64;
217	    let mut entropy = 0.0;
218	    for &count in &freq {
219	        if count > 0 {
220	            let p = count as f64 / len;
221	            entropy -= p * p.log2();
222	        }
223	    }
224	    entropy
225	}
